BEGIN;
-- Additive preproduction containment; preserve all existing identity credentials/factors.
ALTER TABLE "User" ADD COLUMN "isPlatformAdmin" boolean NOT NULL DEFAULT false;
UPDATE "User" SET "isPlatformAdmin"=true WHERE username='adam' AND role='admin' AND "isActive"=true;
CREATE TABLE "WarehouseSite" (id text PRIMARY KEY,slug text NOT NULL UNIQUE,name text NOT NULL,"isActive" boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,configuration jsonb NOT NULL DEFAULT '{}',"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "WarehouseMembership" (id text PRIMARY KEY,"siteId" text NOT NULL REFERENCES "WarehouseSite"(id),"userId" text NOT NULL REFERENCES "User"(id),"isActive" boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("siteId","userId"));
CREATE TABLE "WarehouseRole" (id text PRIMARY KEY,"siteId" text REFERENCES "WarehouseSite"(id),name text NOT NULL,capabilities text[] NOT NULL,"isActive" boolean NOT NULL DEFAULT true,"isTemplate" boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "WarehouseMembershipRole" ("membershipId" text NOT NULL REFERENCES "WarehouseMembership"(id) ON DELETE CASCADE,"roleId" text NOT NULL REFERENCES "WarehouseRole"(id),PRIMARY KEY("membershipId","roleId"));
INSERT INTO "WarehouseSite"(id,slug,name) VALUES('warehouse-initial','initial','Initial warehouse');
INSERT INTO "WarehouseRole"(id,name,capabilities,"isTemplate") VALUES
('warehouse-operator','Operator',ARRAY['inventory.read','inventory.write','workflow.read','workflow.execute','labels.read','labels.print'],true),
('warehouse-manager','Site Manager',ARRAY['inventory.read','inventory.write','inventory.identify','workflow.read','workflow.execute','labels.read','labels.print','labels.manage','files.manage','office.decide','office.authorize_rtv','dispatch.allocate','dispatch.signoff','sites.members.manage','sites.configure','integrations.manage','providers.manage','workflows.manage'],true);
INSERT INTO "WarehouseMembership"(id,"siteId","userId","isActive") SELECT 'initial:'||id,'warehouse-initial',id,"isActive" FROM "User";
INSERT INTO "WarehouseMembershipRole"("membershipId","roleId") SELECT 'initial:'||id,CASE WHEN role IN ('admin','manager') THEN 'warehouse-manager' ELSE 'warehouse-operator' END FROM "User";
ALTER TABLE "UserSession" ADD COLUMN "activeSiteId" text NOT NULL DEFAULT 'warehouse-initial' REFERENCES "WarehouseSite"(id);
ALTER TABLE "OAuthGrant" ADD COLUMN "siteId" text NOT NULL DEFAULT 'warehouse-initial' REFERENCES "WarehouseSite"(id);
ALTER TABLE "AppAccessGrant" ADD COLUMN "siteId" text NOT NULL DEFAULT 'warehouse-initial' REFERENCES "WarehouseSite"(id);
ALTER TABLE "OAuthAuthorizationRequest" ADD COLUMN "siteId" text REFERENCES "WarehouseSite"(id);
ALTER TABLE "IdentityAudit" ADD COLUMN "siteId" text DEFAULT nullif(current_setting('temco.site_id',true),'') REFERENCES "WarehouseSite"(id);
-- Pipeline existed in Prisma without a corresponding published migration.
-- Retain the model, creating its empty table only when absent.
CREATE TABLE IF NOT EXISTS "Pipeline" (id text PRIMARY KEY,name text NOT NULL,steps jsonb NOT NULL DEFAULT '[]',"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamp(3) NOT NULL);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='temco_runtime') THEN CREATE ROLE temco_runtime NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
ALTER ROLE temco_runtime NOSUPERUSER NOBYPASSRLS NOLOGIN;
DO $$ BEGIN EXECUTE format('GRANT temco_runtime TO %I',current_user); END $$;
GRANT USAGE ON SCHEMA public TO temco_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO temco_runtime;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO temco_runtime;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT,INSERT,UPDATE,DELETE ON TABLES TO temco_runtime;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE,SELECT ON SEQUENCES TO temco_runtime;
CREATE FUNCTION public.temco_site_authorized(target_site text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $func$
 SELECT target_site = nullif(current_setting('temco.site_id',true),'') AND EXISTS(
 SELECT 1 FROM public."User" u JOIN public."UserSession" s ON s."userId"=u.id JOIN public."WarehouseSite" w ON w.id=target_site
 WHERE u.id=nullif(current_setting('temco.user_id',true),'') AND s.id=nullif(current_setting('temco.session_id',true),'')
 AND u."isActive" AND w."isActive" AND u."authVersion"=s."authVersion" AND s."authVersion"=nullif(current_setting('temco.auth_version',true),'')::integer
 AND s."revokedAt" IS NULL AND s."lockedAt" IS NULL AND s."expiresAt">now() AND s."lastActivityAt">now()-interval '30 minutes'
 AND (u."isPlatformAdmin" OR EXISTS(SELECT 1 FROM public."WarehouseMembership" m WHERE m."siteId"=target_site AND m."userId"=u.id AND m."isActive")))
$func$;
REVOKE ALL ON FUNCTION public.temco_site_authorized(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.temco_site_authorized(text) TO temco_runtime;
