ALTER TABLE "DmpOperation" ADD CONSTRAINT "DmpOperation_siteId_fkey" FOREIGN KEY("siteId") REFERENCES "WarehouseSite"(id);
CREATE INDEX "DmpOperation_siteId_idx" ON "DmpOperation"("siteId");
ALTER TABLE "DmpOperation" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "DmpOperation" FORCE ROW LEVEL SECURITY;
CREATE POLICY warehouse_isolation ON "DmpOperation" USING(public.temco_site_authorized("siteId")) WITH CHECK(public.temco_site_authorized("siteId"));
